import re
import os
import json
import logging
import xml.dom.minidom
from moler.device import DeviceFactory
from moler.util.moler_test import MolerTest
from taf.rfrl.bts.devices.cu.generic_cu import GenericCu, login_logout
from taf.rfrl.bts.devices.exceptions import WrongCounterValue, CounterIncrementationFailed, CannotGetCounterValue
from taf.rfrl.bts.devices.cu.commissioning import CuCommissioning
from taf.rfrl.bts.connections import device_aliases
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.test_config import get_log_path
from taf.rfrl.utilities.transfer_files import download_files


class CuPmCounter(GenericCu):
    """Counter keywords for CU"""

    @login_logout
    def get_pm_interval(self, param_name, abbr_group_name, bts_id=0, du_id=0):
        """
        Get the current parameter value for abbr
        :param param_name: parameter name filter to locate target measurement.
        :param abbr_group_name: Abbreviation e.g. miNrRacCu
        :param mrbts: This is the instance identifier of MRBTS object
        :param nrbts: This parameter uniquely identifies the New Radio Basestation
        :return: value for abbr
        """
        dist_name = "MRBTS-{}/NRBTS-{}/NRPMRNL-1"
        dist_name = self.adjust_dist_name(dist_name, bts_id, du_id)
        return CuCommissioning().get_cu_parameter_value_via_gui(dist_name, param_name, abbr_group_name, bts_id=bts_id,
                                                                du_id=du_id)

    @load_moler_configuration_from_tl()
    def download_cu_pm_counter_file(self, counter_id, log_dir=None, bts_id=0, timeout=180):
        """
        Download CU PM counters file from OAM vm file system.

        :param bts_id: ID of BTS
        :param log_dir: directory where report will be collected
        :param counter_id: general counters ID (e.g. M55121C00006)
        :param timeout: timeout for scp.
        """
        if log_dir is None:
            log_dir = get_log_path()
        bts = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        bts.goto_state("OAM")
        counters_id_regex = re.compile(r'M(?P<COUNTER_ID>\d+)C\d+')
        counters_id = counters_id_regex.search(counter_id).group('COUNTER_ID')
        pm_data_path = "/var/opt/nokia/performancemanagement/storage/results/"
        cat_cmd = bts.get_cmd(cmd_name="cat", cmd_params={"path": os.path.join(pm_data_path, "resultMapping.json")})
        try:
            pm_src_file_name = json.loads("".join(cat_cmd()["LINES"]))[counters_id]["filenames"][0]
        except KeyError:
            MolerTest.error("Provided counters_id ({}) NOT exist".format(counters_id), raise_exception=True)
            return None
        mkdir_cmd = bts.get_cmd(cmd_name='mkdir', cmd_params={'path': r"/tmp/logs"})
        mkdir_cmd()
        cp_pm_src_file = bts.get_cmd(cmd_name='cp',
                                     cmd_params={'src': os.path.join(pm_data_path, pm_src_file_name),
                                                 'dst': r"/tmp/logs"})
        sudo_cp_pm_src_file = bts.get_cmd(cmd_name='sudo', cmd_params={'cmd_object': cp_pm_src_file})
        sudo_cp_pm_src_file()
        chmod_ps_src_file = bts.get_cmd(cmd_name='chmod', cmd_params={'permission': 777,
                                                                      'filename': os.path.join(r"/tmp/logs",
                                                                                               pm_src_file_name)})
        sudo_chmod_ps_src_file = bts.get_cmd(cmd_name='sudo', cmd_params={'cmd_object': chmod_ps_src_file})
        sudo_chmod_ps_src_file()
        extract_xml_file = bts.get_cmd(cmd_name='gzip', cmd_params={'file_name': os.path.join(r"/tmp/logs",
                                                                                              pm_src_file_name),
                                                                    'options': r'-d'})
        sudo_extract_xml_file = bts.get_cmd(cmd_name='sudo', cmd_params={'cmd_object': extract_xml_file})
        sudo_extract_xml_file()
        download_files(local_dir=log_dir,
                       remote_file=pm_src_file_name.replace('.gz', ''),
                       remote_dir="/tmp/logs",
                       device_name=device_aliases.ssh_gnb_cu.format(bts_id),
                       from_state='OAM',
                       timeout=timeout)
        rm_cmd = bts.get_cmd(cmd_name='rm', cmd_params={'file': "/tmp/logs/", 'options': r"-r"})
        sudo_rm_cmd = bts.get_cmd(cmd_name='sudo', cmd_params={'cmd_object': rm_cmd})
        sudo_rm_cmd()
        return os.path.join(log_dir, pm_src_file_name.replace('.gz', ''))

    @load_moler_configuration_from_tl()
    def get_cu_pm_counter_value(self, counter_id, network_element_dist_name, log_dir=None, bts_id=0, du_id=0,
                                timeout=180):
        """
        Get PM counters values from OAM vm file system.

        :param bts_id: ID of BTS
        :param log_dir: directory where report will be collected
        :param counter_id: general counters ID (e.g. M55121C00006)
        :param network_element_dist_name: dist name to locate the parameter.
               (e.g. MRBTS-{}/NRBTS-{}/NRCELL-1)
        :param timeout: timeout for scp.
        """
        dist_name = self.adjust_dist_name(network_element_dist_name, bts_id, du_id)
        cu_pm_counter_file = self.download_cu_pm_counter_file(counter_id, log_dir, bts_id, timeout)
        doc = xml.dom.minidom.parse(cu_pm_counter_file)
        try:
            for PMMOResult in doc.getElementsByTagName('PMMOResult'):
                for MO_element in PMMOResult.getElementsByTagName('MO'):
                    for DN_element in MO_element.getElementsByTagName('DN'):
                        if DN_element.firstChild.nodeValue == ''.join(["PLMN-PLMN/", dist_name]):
                            for PMTarget in PMMOResult.getElementsByTagName('PMTarget'):
                                counters = PMTarget.getElementsByTagName(counter_id)
                                return int(counters[0].firstChild.nodeValue)
        except CannotGetCounterValue:
            logging.debug("Counter {} does not exists".format(counter_id))
        return None

    def verify_cu_pm_counter_value(self, counter_id, network_element_dist_name, counter_value):
        """
        Verify PM counter value from OAM vm file system.

        :param counter_id: general counter ID (e.g. M55121C00006)
        :param network_element_dist_name: dist name to locate the parameter.
        :param counter_value: predicted value of given counter
        """
        cu_pm_counter_value = self.get_cu_pm_counter_value(counter_id, network_element_dist_name)
        if cu_pm_counter_value != int(counter_value):
            raise WrongCounterValue("Wrong counter {} value: {} != {}".format(counter_id,
                                                                              cu_pm_counter_value,
                                                                              counter_value))

    @staticmethod
    def verify_cu_pm_counter_incrementation(value_before_incrementation, value_after_incrementation):
        """
        Verify PM counter incrementation.

        :param value_before_incrementation: general counter ID (e.g. M55121C00006)
        :param value_after_incrementation: predicted value of given counter
        """
        if value_before_incrementation >= value_after_incrementation:
            raise CounterIncrementationFailed("Value before incrementation: {}\n"
                                              "Value after incrementation: {}".format(value_before_incrementation,
                                                                                      value_after_incrementation))
